-- Restricted F4 snapshot resolution. Requires exact admitted Central 030 predecessor.
-- Additive authority operation; no new runtime table grants, memberships or PUBLIC execution.
DO $migration$
DECLARE definition text; needle constant text := ' CASE query_code';
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='authority_api.execute(text,text[],text)'::regprocedure AND prosecdef AND pg_get_userbyid(proowner)='c4g_authority_owner' AND proconfig=ARRAY['search_path=pg_catalog, public, pg_temp']) THEN RAISE EXCEPTION 'DIRECTORY_PROTOCOL_SECURITY_DRIFT'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='c4g_authority_owner' AND (rolcanlogin OR rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb OR rolinherit)) THEN RAISE EXCEPTION 'DIRECTORY_OWNER_DRIFT'; END IF;
 SELECT pg_get_functiondef('authority_api.execute(text,text[],text)'::regprocedure) INTO STRICT definition;
 IF (length(definition)-length(replace(definition,needle,'')))<>length(needle) THEN RAISE EXCEPTION 'DIRECTORY_PROTOCOL_PATCH_POINT_INVALID'; END IF;
 IF position('542e560d6846ec65effbcfc82657b89616fa00efbf1c5ffdfb63f3270c51a5a4' in definition)>0 THEN RAISE EXCEPTION 'DIRECTORY_PROTOCOL_ALREADY_PRESENT'; END IF;
 EXECUTE replace(definition,needle,needle||$cases$
 WHEN '542e560d6846ec65effbcfc82657b89616fa00efbf1c5ffdfb63f3270c51a5a4' THEN statement:='SELECT o.id organization_id,t.tenant_id,t.deployment_mode,wb.provisioning_status, wb.workload,wb.current_connection_version,wb.lifecycle_status operational_state,wb.revision connection_revision,wb.fence workload_fence, v.version_state,v.database_generation_id,g.database_ref,wv.credential_ref, v.region_code,v.residency_policy_version,v.observed_system_identifier,wv.binding_digest, wb.compatibility_status compatibility_state,s.current_version,s.minimum_read_version,s.minimum_write_version,s.verified_capabilities,s.revision schema_revision FROM public.organization o JOIN public.tenant t ON t.organization_id=o.id JOIN public.tenant_workload_binding wb ON wb.tenant_id=t.tenant_id AND wb.workload=$2 JOIN public.tenant_workload_connection_version wv ON wv.tenant_id=wb.tenant_id AND wv.workload=wb.workload AND wv.connection_version=wb.current_connection_version JOIN public.organization_connection_version v ON v.tenant_id=wv.tenant_id AND v.connection_version=wv.connection_version JOIN public.tenant_database_generation g ON g.tenant_id=v.tenant_id AND g.database_generation_id=v.database_generation_id JOIN public.tenant_schema_state s ON s.tenant_id=t.tenant_id WHERE o.id=$1 AND o.status=''ACTIVE'' AND $2 IN (''API'',''WORKER'') AND t.deployment_mode=''DATABASE_PER_ORGANIZATION'' AND wb.lifecycle_status=''AVAILABLE'' AND wb.provisioning_status=''READY'' AND wb.compatibility_status IN (''COMPATIBLE'',''READ_ONLY'') AND wv.lifecycle_status=''AVAILABLE'' AND wv.provisioning_status=''READY'' AND wv.compatibility_status IN (''COMPATIBLE'',''READ_ONLY'') AND v.version_state=''VALIDATED'' AND wb.credential_ref=wv.credential_ref AND wb.binding_digest=wv.binding_digest AND wb.fence=wv.fence AND g.retired_at IS NULL LIMIT 2';
$cases$);
END $migration$;
GRANT SELECT(tenant_id,connection_version,version_state,database_generation_id,region_code,residency_policy_version,observed_system_identifier) ON public.organization_connection_version TO c4g_authority_owner;
GRANT SELECT(tenant_id,database_generation_id,database_ref,retired_at) ON public.tenant_database_generation TO c4g_authority_owner;
GRANT SELECT(tenant_id,workload,connection_version,credential_ref,binding_digest,lifecycle_status,provisioning_status,compatibility_status,fence) ON public.tenant_workload_connection_version TO c4g_authority_owner;
